<section class="payment-result-page"><div class="container container--sm"><div class="payment-result <?= $successful ? 'payment-result--success' : 'payment-result--failed' ?>"><span class="payment-result__icon"><?= $successful ? '✓' : '×' ?></span><span class="eyebrow">Payment Result</span><h1><?= $successful ? 'پرداخت با موفقیت انجام شد' : 'پرداخت نهایی نشد' ?></h1><p><?= $successful ? 'ثبت‌نام شما قطعی شد و دوره به بخش «دوره‌های من» اضافه شد.' : 'مبلغی تأیید نشده است. می‌توانید سفارش را بررسی یا دوباره تلاش کنید.' ?></p><?php if ($order): ?><dl class="payment-result__receipt"><div><dt>شماره سفارش</dt><dd class="ltr"><?= e($order['number']) ?></dd></div><div><dt>عنوان</dt><dd><?= e($order['item_title']) ?></dd></div><div><dt>مبلغ</dt><dd><?= number_format((int) $order['amount']) ?> تومان</dd></div><div><dt>وضعیت</dt><dd><span class="order-status order-status--<?= e($order['status']) ?>"><?= $order['status'] === 'paid' ? 'پرداخت‌شده' : 'ناموفق / لغوشده' ?></span></dd></div></dl><?php endif; ?><div class="cluster center"><?php if ($successful): ?><a class="btn btn--primary btn--lg" href="/my-courses">رفتن به دوره‌های من</a><?php elseif ($order): ?><a class="btn btn--primary btn--lg" href="/orders/<?= e($order['id']) ?>">بررسی سفارش</a><?php endif; ?><a class="btn btn--ghost btn--lg" href="/orders">سفارش‌های من</a></div></div></div></section>
